## Build S13 Table (PDF source) and the S14 File archive contents from the systematic-run results.
## Run: OMP_NUM_THREADS=1 distrobox enter emacs-r -- Rscript make-S13-S14.R
suppressMessages(library(data.table))
si <- "/var/home/aoz/Dropbox/genetics/a-s-omics/Submission_PLOSOne/submission-2/supporting-information"
ko <- "/var/home/aoz/data/a-s-omics-uncertainty/klone-out"
ck <- fread(file.path(ko, "check2.csv")); reg <- fread("results/regional.csv"); crx <- fread("/var/home/aoz/data/a-s-omics-uncertainty/crossfield.csv")
P <- fread("stage/pairs.csv"); fg <- ck[flag == TRUE]
fp <- P[Lg %in% fg$gene | Rg %in% fg$gene]
fr <- fread("results/flagged-refit-plugin.csv")
tab <- function(d, T0) d[, .(ld = sum(pmax(plug_ratio, 1/plug_ratio) >= T0), ldnc = sum(pmax(plug_ratio, 1/plug_ratio) >= T0 & !credible),
                            lac = sum(pmax(plug_ratio, 1/plug_ratio) < T0 & credible), n = .N)]
f <- function(x) format(x, big.mark = ",")
rows <- c()
for (T0 in c(1.25, 1.5, 2)) for (w in c("all", "excl")) {
  a <- tab(if (w == "all") reg else reg[flagged == FALSE], T0); b <- tab(if (w == "all") crx else crx[flagged == FALSE], T0)
  rows <- c(rows, sprintf("%s & %s & %s & %s & %s & %s & %s & %s \\\\", T0, ifelse(w == "all", "all pairs", "flagged pairs excluded"),
                          f(a$n), f(a$ld), f(a$ldnc), f(a$lac), f(b$ld), f(b$ldnc)))
}
tex <- c("% S13 Table. Generated by code-spatial-smoothing/uncertainty/klone/make-S13-S14.R; do not edit by hand.",
"\\documentclass[10pt]{article}\\usepackage[margin=0.8in]{geometry}\\usepackage{booktabs}\\usepackage{parskip}\\begin{document}",
"\\begin{center}{\\large\\bfseries S13 Table. Reproduction of the published fits by the refits, and its effect on the counts.}\\\\[3pt]\\emph{Osgood-Zimmerman \\& Raredon}\\end{center}",
sprintf("Of the 790 genes refitted with the published model specification, %d reproduce the stored per-bin posterior medians and 95\\%% interval widths of the published fits within Monte Carlo error. A gene is flagged when, over 2,000 fixed bins, the median difference between the refit and published posterior medians exceeds 0.04 on the log scale, or the median ratio of 95\\%% interval widths (log scale) falls outside 0.9 to 1.1; differences between two independent sets of draws from one refit stayed within 0.02 and 0.96 to 1.04 for seven genes checked. The full per-gene check is in S14 File (\\texttt{check2.csv}).", sum(!ck$flag)),
"", "\\textbf{(A) Flagged genes.}", "", "\\begin{tabular}{lrr}\\toprule Gene & Median log difference & Width ratio \\\\ \\midrule",
fg[, sprintf("\\textit{%s} & %.3f & %.2f \\\\", gene, med_dlog, width_ratio)], "\\bottomrule\\end{tabular}", "",
sprintf("\\textbf{(B) The %d ligand-receptor pairs involving a flagged gene.} %s.", nrow(fp), paste(fp$pair, collapse = ", ")), "",
"\\textbf{(C) Counts with and without the flagged pairs.} Same-field region comparisons (1,477 pairs $\\times$ 13 comparisons) and cross-field comparisons (pairs of fields sharing a ligand or receptor, $\\times$ 10 regions). LD: looks different (plug-in ratio $\\ge T$); LD-NC: looks different, not credible; LA-C: looks alike, credible.", "",
"\\begin{tabular}{llrrrrrr}\\toprule $T$ & Pairs & $n$ & LD & LD-NC & LA-C & Cross LD & Cross LD-NC \\\\ \\midrule", rows, "\\bottomrule\\end{tabular}", "",
sprintf("\\textbf{(D) Plug-in reading from the refit.} For the %d region comparisons of the flagged pairs, \\textit{looks different} at $T = 1.25$ was recomputed from the refit's own posterior medians instead of the published fit: %d of %d calls agree; the number that look different but are not credible is %d with the refit plug-in and %d with the published one. Per-comparison values are in S14 File (\\texttt{flagged-refit-plugin.csv}).",
  nrow(fr), sum(fr$ld_pub == fr$ld_refit), nrow(fr), sum(fr$ld_refit & !fr$credible), sum(fr$ld_pub & !fr$credible)),
"\\end{document}")
writeLines(tex, file.path(si, "S13_Table.tex"))
## S14 File contents
d14 <- file.path(si, "S14_File"); dir.create(d14, showWarnings = FALSE)
fwrite(reg, file.path(d14, "regional.csv")); fwrite(crx, file.path(d14, "crossfield.csv"))
file.copy("results/slices.csv", d14, overwrite = TRUE); fwrite(ck, file.path(d14, "check2.csv"))
file.copy("results/flagged-refit-plugin.csv", d14, overwrite = TRUE)
writeLines(c("S14 File. Per-pair results of the uncertainty-aware comparisons (Osgood-Zimmerman & Raredon).",
"",
"regional.csv: one row per ligand-receptor pair and fixed region comparison (1,477 x 13). plug_ratio: ratio of regional",
"  averages on the published plug-in map (first region / second); wilcox_p: two-sided Wilcoxon rank-sum p, bins as",
"  independent; post_med, lo, hi: posterior median and 95% interval of the ratio; credible: interval excludes 1;",
"  dec_lo, dec_hi, dec_credible: the same with each bin's draws permuted independently; flagged: pair involves a gene",
"  whose refit differs from the published fit (S13 Table).",
"crossfield.csv: one row per pair of fields sharing a ligand or receptor (a, b) and region; each field divided by its",
"  own field-of-view average within each draw; wilcox_signed_p: paired Wilcoxon signed-rank on the plug-in fields.",
"slices.csv: one row per pair and transect: n positions; n_pointwise: positions with posterior probability >= 0.95 of",
"  being above or below the transect average; n_simband: positions where the simultaneous 95% band excludes 0;",
"  n_joint: positions in the joint 95% excursion sets; ld_T, ld_T_joint: positions that look different at threshold T",
"  (|plug-in log deviation| >= log T), and how many of those are in the joint sets; alike_joint_125: positions that",
"  look alike at T = 1.25 but are in the joint sets.",
"check2.csv: per-gene reproduction check (med_dlog, width_ratio, flag).",
"flagged-refit-plugin.csv: flagged pairs with the plug-in ratio from the published fit and from the refit."), file.path(d14, "README.txt"))
cat("ok\n")
